  ('accra-airport-1', 'Executive Airport Residential Villa', 'Accra', 'Airport Residential', 'Rent', 'Townhouse', 8500, 'month', 3, 3, 210, true, 2, 'Published', true, 'A calm, spacious luxury residence close to Accra''s business district, with generous living areas, balconies and a landscaped compound.', ARRAY['Swimming pool', '24/7 security', 'Backup generator', 'Parking', 'Air conditioning', 'Wi-Fi']::text[], ARRAY['https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1400&q=80']::text[], now() - interval '0 minutes'),
  ('accra-east-legon-2', 'Modern East Legon Residence', 'Accra', 'East Legon', 'Sale', '3-Bed', 1200000, 'sale', 3, 3, 185, false, 2, 'Published', true, 'Contemporary three-bedroom home designed for comfortable family living in a sought-after East Legon setting.', ARRAY['Gym', 'CCTV', 'Parking', 'Balcony', 'Air conditioning']::text[], ARRAY['https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?auto=format&fit=crop&w=1400&q=80']::text[], now() - interval '1 minutes'),
  ('accra-labone-3', 'Elegant Labone City Apartment', 'Accra', 'Labone', 'Rent', '2-Bed', 6500, 'month', 2, 2, 130, true, 1, 'Published', true, 'An elegant furnished apartment with modern finishes, natural light and easy access to restaurants, offices and the coast.', ARRAY['24/7 security', 'Wi-Fi', 'Parking', 'CCTV']::text[], ARRAY['https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1600607688969-a5bfcd646154?auto=format&fit=crop&w=1400&q=80']::text[], now() - interval '2 minutes'),
  ('kumasi-nhyiaeso-1', 'Nhyiaeso Family Haven', 'Kumasi', 'Nhyiaeso', 'Rent', '4-Bed+', 9000, 'month', 4, 4, 260, true, 3, 'Published', true, 'A generous family home in a quiet premium neighbourhood with room for entertaining and long stays.', ARRAY['Backup generator', 'Parking', '24/7 security', 'Air conditioning']::text[], ARRAY['https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1600607688969-a5bfcd646154?auto=format&fit=crop&w=1400&q=80']::text[], now() - interval '3 minutes'),
  ('kumasi-ahodwo-2', 'Ahodwo Luxury Apartment', 'Kumasi', 'Ahodwo', 'Sale', '3-Bed', 980000, 'sale', 3, 3, 175, false, 2, 'Published', false, 'A polished three-bedroom residence with premium finishes and convenient access to central Kumasi.', ARRAY['Gym', 'CCTV', 'Parking', 'Balcony']::text[], ARRAY['https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1400&q=80']::text[], now() - interval '4 minutes'),
  ('kumasi-asuoyeboa-3', 'Private Asuoyeboa Retreat', 'Kumasi', 'Asuoyeboa', 'Rent', '2-Bed', 4200, 'month', 2, 2, 115, true, 1, 'Published', false, 'A comfortable furnished apartment suited to professionals and small families seeking a peaceful base in Kumasi.', ARRAY['24/7 security', 'Parking', 'Wi-Fi']::text[], ARRAY['https://images.unsplash.com/photo-1600607688969-a5bfcd646154?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1400&q=80']::text[], now() - interval '5 minutes'),
  ('cape-fosu-1', 'Fosu Lagoon Coastal Residence', 'Cape Coast', 'Fosu Lagoon', 'Rent', '2-Bed', 5000, 'month', 2, 2, 125, true, 1, 'Published', true, 'Relaxed coastal living near Fosu Lagoon, with bright interiors and an easy route to beaches and town.', ARRAY['Sea view', 'Parking', 'Air conditioning', 'Wi-Fi']::text[], ARRAY['https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1600607688969-a5bfcd646154?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1400&q=80']::text[], now() - interval '6 minutes'),
  ('cape-elmina-2', 'Elmina Road Heritage Villa', 'Cape Coast', 'Elmina Road', 'Sale', 'Townhouse', 1100000, 'sale', 3, 3, 220, false, 2, 'Published', false, 'A spacious villa-style property positioned for coastal retreats and access to heritage destinations.', ARRAY['Sea view', 'Parking', 'Backup generator', 'Balcony']::text[], ARRAY['https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?auto=format&fit=crop&w=1400&q=80']::text[], now() - interval '7 minutes'),
